export type TranslationKey = typeof entries[number][0];
export const dictionaries = Object.fromEntries(locales.map((locale, index) => [
  locale.code, Object.fromEntries(entries.map((row) => [row[0], row[index + 1]])),
])) as Record<Locale, Partial<Record<TranslationKey, string>>>;

export function translate(locale: Locale, key: TranslationKey, variables: Variables = {}) {
  const template = dictionaries[locale]?.[key] || dictionaries.es[key] || key;
  return template.replace(/\{(\w+)\}/g, (match, name: string) => String(variables[name] ?? match));
}

const sourceKeys = new Map<string, TranslationKey>(entries.map((row) => [row[1], row[0]]));
// For existing UI messages kept in state, translate at render time so switching
// language updates the message without rerunning authentication or data requests.
export function translateText(locale: Locale, source: string) {
  const key = sourceKeys.get(source);
  return key ? translate(locale, key) : source;
}
